import shutil, openpyxl
shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb["denomination"]
vws = vals["denomination"]

den = []
for col in range(8, 17):
    v = vws.cell(row=1, column=col).value
    den.append(int(v))

n_emp = 7
salaries = []
for r in range(2, 2+n_emp):
    v = vws.cell(row=r, column=5).value
    salaries.append(int(v) if v is not None else 0)

target = [0]*len(den)
for r in range(13, 22):
    d = vws.cell(row=r, column=3).value
    cnt = vws.cell(row=r, column=4).value
    if d is None:
        continue
    d = int(d)
    if d in den:
        target[den.index(d)] = int(cnt) if cnt is not None else 0

def greedy():
    alloc = [[0]*len(den) for _ in range(n_emp)]
    rem_target = target[:]
    for i, s in enumerate(salaries):
        rem = s
        for j, d in enumerate(den):
            if rem <= 0:
                break
            if rem_target[j] <= 0:
                continue
            use = min(rem // d, rem_target[j])
            if use:
                alloc[i][j] = use
                rem -= use * d
                rem_target[j] -= use
        if rem != 0:
            return None
    # verify
    for i, s in enumerate(salaries):
        if sum(alloc[i][j] * den[j] for j in range(len(den))) != s:
            return None
    for j in range(len(den)):
        if sum(alloc[i][j] for i in range(n_emp)) != target[j]:
            return None
    return alloc

def make_combo_generator(den_list, max_counts):
    n = len(den_list)
    suffix_max = [0]*(n+1)
    for i in range(n-1, -1, -1):
        suffix_max[i] = suffix_max[i+1] + max_counts[i]*den_list[i]
    def gen(rem):
        res = []
        cur = [0]*n
        def rec(i, r):
            if r < 0 or r > suffix_max[i]:
                return
            if i == n:
                if r == 0:
                    res.append(tuple(cur))
                return
            d = den_list[i]
            max_c = min(max_counts[i], r // d)
            min_c = 0
            if r > suffix_max[i+1]:
                min_c = (r - suffix_max[i+1] + d - 1) // d
            for c in range(min_c, max_c + 1):
                cur[i] = c
                rec(i+1, r - c*d)
        rec(0, rem)
        res.sort(key=lambda x: (sum(x), x))
        return res
    return gen

def solve_lower():
    if 1000 not in den:
        return None
    idx1000 = den.index(1000)
    if sum(s // 1000 for s in salaries) != target[idx1000]:
        return None
    lower_idx = [j for j in range(len(den)) if j != idx1000]
    lower_den = [den[j] for j in lower_idx]
    lower_target = [target[j] for j in lower_idx]
    remainders = [s - (s // 1000) * 1000 for s in salaries]
    gen = make_combo_generator(lower_den, lower_target)
    combos = [gen(rem) for rem in remainders]
    if any(len(c) == 0 for c in combos):
        return None
    order = sorted(range(n_emp), key=lambda i: len(combos[i]))
    alloc = [[0]*len(den) for _ in range(n_emp)]
    for i in range(n_emp):
        alloc[i][idx1000] = salaries[i] // 1000
    def bt(pos, rem_counts):
        if pos == len(order):
            return all(x == 0 for x in rem_counts)
        i = order[pos]
        for combo in combos[i]:
            if all(combo[k] <= rem_counts[k] for k in range(len(lower_den))):
                new = [rem_counts[k] - combo[k] for k in range(len(lower_den))]
                if bt(pos+1, new):
                    for k, j in enumerate(lower_idx):
                        alloc[i][j] = combo[k]
                    return True
        return False
    if bt(0, lower_target[:]):
        return alloc
    return None

def solve_full():
    gen = make_combo_generator(den, target)
    combos = [gen(s) for s in salaries]
    if any(len(c) == 0 for c in combos):
        return None
    order = sorted(range(n_emp), key=lambda i: len(combos[i]))
    alloc = [[0]*len(den) for _ in range(n_emp)]
    def bt(pos, rem_counts):
        if pos == len(order):
            return all(x == 0 for x in rem_counts)
        i = order[pos]
        for combo in combos[i]:
            if all(combo[k] <= rem_counts[k] for k in range(len(den))):
                new = [rem_counts[k] - combo[k] for k in range(len(den))]
                if bt(pos+1, new):
                    alloc[i] = list(combo)
                    return True
        return False
    if bt(0, target[:]):
        return alloc
    return None

alloc = greedy()
if alloc is None:
    alloc = solve_lower()
if alloc is None:
    alloc = solve_full()
if alloc is None:
    # final fallback: greedy without verification? But greedy returned None if rem not zero or target mismatch.
    # Use a simple canonical allocation: floor 1000, then greedy over remaining denominations ignoring target.
    alloc = [[0]*len(den) for _ in range(n_emp)]
    for i, s in enumerate(salaries):
        rem = s
        for j, d in enumerate(den):
            if rem <= 0: break
            use = rem // d
            alloc[i][j] = use
            rem -= use * d
# write
for i in range(n_emp):
    for j in range(len(den)):
        ws.cell(row=2+i, column=8+j).value = int(alloc[i][j])
wb.save(OUT)
print("salaries", salaries)
print("target", target)
print("alloc", alloc)
print("col_sums", [sum(alloc[i][j] for i in range(n_emp)) for j in range(len(den))])
print("row_amounts", [sum(alloc[i][j]*den[j] for j in range(len(den))) for i in range(n_emp)])
